<script setup>
import {computed} from 'vue'
import carePhoto from '../assets/admin/customer-care.webp'
import auditPhoto from '../assets/admin/quality-records.webp'
import DeviceArt from './illustrations/DeviceArt.vue'
import PartArt from './illustrations/PartArt.vue'
import StatusArt from './illustrations/StatusArt.vue'
import PersonAvatar from './ui/PersonAvatar.vue'
import SvgIcon from './ui/SvgIcon.vue'
import {equipmentArt} from '../data/equipmentPresentation'
import {countLabel} from '../data/presentationCount'
import {adminClients,adminMasters,adminSkills,adminServices,adminRequests,adminParts,auditEvents,purchaseOrders,activeStatuses} from '../data/admin'
import {adminPoints,adminSuppliers,adminPartKind} from '../data/adminOperations'
const props=defineProps({entity:String,selected:{type:String,default:''}})
const emit=defineEmits(['filter','client'])
const activeRequests=computed(()=>adminRequests.filter(r=>activeStatuses.includes(r.status)))
const activeClients=computed(()=>adminClients.filter(c=>activeRequests.value.some(r=>r.user_id===c.id)))
const recentClients=computed(()=>[...new Set(adminRequests.map(r=>r.user_id))].map(id=>adminClients.find(c=>c.id===id)).filter(Boolean).slice(0,3))
const stages=computed(()=>[{code:'new',title:'Первый контакт',caption:'Проверить данные'},{code:'confirmed',title:'Подбор мастера',caption:'Назначить исполнителя'},{code:'assigned',title:'Мастер назначен',caption:'Ближайшие работы'},{code:'waiting_parts',title:'Ожидают детали',caption:'Проверить снабжение'}].map(s=>({...s,count:adminRequests.filter(r=>r.status===s.code).length})))
const formats=computed(()=>[{name:'Выезд к клиенту',icon:'home',field:'is_onsite'},{name:'Ремонт в сервисе',icon:'store',field:'is_dropoff'}].map(f=>({...f,masters:adminMasters.filter(m=>m[f.field]&&m.is_available)})))
const both=computed(()=>adminMasters.filter(m=>m.is_onsite&&m.is_dropoff&&m.is_available).length)
const coverage=computed(()=>[...new Set(adminServices.map(s=>s.equipment_category))].map(name=>{const services=adminServices.filter(s=>s.is_active&&s.equipment_category===name);const covered=services.filter(s=>adminSkills.some(k=>k.service_id===s.id&&k.skill_level>=s.required_skill_level&&adminMasters.some(m=>m.id===k.master_id&&m.is_available)));return {name,total:services.length,covered:covered.length}}).filter(c=>c.total))
const roleLabels={admin:'Администраторы',master:'Мастера',client:'Клиенты',system:'Система'}
const roleColors={admin:'var(--blue)',master:'var(--purple)',client:'var(--green)',system:'var(--muted)'}
const roles=computed(()=>Object.entries(roleLabels).map(([key,label])=>({key,label,color:roleColors[key],count:auditEvents.filter(e=>e.role===key).length})))
const activePoints=computed(()=>adminPoints.filter(p=>p.is_active).length)
const dropoff=computed(()=>adminRequests.filter(r=>r.service_mode==='dropoff'&&activeStatuses.includes(r.status)).length)
const partners=computed(()=>adminSuppliers.filter(s=>s.is_active).map(s=>({...s,parts:adminParts.filter(p=>p.is_active&&p.supplier_id===s.id),orders:purchaseOrders.filter(o=>o.supplier_id===s.id&&o.status!=='received')})))
</script>
<template>
 <section v-if="entity==='requests'" class="request-lanes" aria-label="Обработка заявок"><div class="admin-context-heading"><div><span class="admin-visual-eyebrow">ОТ ОБРАЩЕНИЯ К РЕЗУЛЬТАТУ</span><h2>Очередь по этапам</h2></div><span>Нажмите этап, чтобы открыть выборку</span></div><div class="request-lane-grid"><button v-for="(s,i) in stages" :key="s.code" :aria-pressed="selected===s.code" type="button" @click="emit('filter',selected===s.code?'':s.code)"><div><StatusArt :status="s.code" :size="38"/><span class="request-lane-step">0{{i+1}}</span></div><strong>{{s.count}}</strong><h3>{{s.title}}</h3><p>{{s.caption}}<SvgIcon name="arrowRight" :size="14"/></p></button></div></section>
 <section v-else-if="entity==='clients'" class="admin-story admin-client-story"><div class="admin-story-photo"><img :src="carePhoto" alt="Сотрудник сервиса обсуждает ремонт с клиентом" loading="lazy"/><span>Внимание к человеку.<br/>Забота о технике.</span></div><div class="admin-story-copy"><span class="admin-visual-eyebrow">СЕРВИС С ЛИЧНЫМ ПОДХОДОМ</span><h2>Контакты и история.<br/>Всё для следующего разговора.</h2><p>Найдите клиента, проверьте контакты и откройте историю его обращений.</p><div class="admin-client-facts"><div><strong>{{activeClients.length}}</strong><span>клиентов с активным ремонтом</span></div><div><strong>{{activeRequests.length}}</strong><span>заявок в работе</span></div></div><div class="admin-recent-people"><span>Недавние обращения</span><div><button v-for="c in recentClients" :key="c.id" type="button" @click="emit('client',c.full_name)"><PersonAvatar :name="c.full_name" :src="c.avatar" :size="33"/><span>{{c.full_name}}</span></button></div></div></div></section>
 <section v-else-if="entity==='masters'" class="admin-team-context"><div class="admin-context-heading"><div><span class="admin-visual-eyebrow">КОМАНДА В ДЕЛЕ</span><h2>Люди, форматы и экспертиза</h2></div><span>{{countLabel(both,'мастер','мастера','мастеров')}} {{both===1?'совмещает':'совмещают'}} оба формата</span></div><div class="admin-team-formats"><div v-for="f in formats" :key="f.field" class="admin-format-card"><div class="admin-format-title"><span><SvgIcon :name="f.icon" :size="21"/></span><h3>{{f.name}}</h3><strong>{{f.masters.length}}</strong></div><div class="admin-format-team"><div class="admin-avatar-stack"><PersonAvatar v-for="m in f.masters.slice(0,4)" :key="m.id" :name="m.full_name" :src="m.avatar" :size="34"/></div><small>{{f.masters.length?'Доступны для назначения':'Нет доступных специалистов'}}</small></div></div></div><div class="admin-team-coverage"><div><h3>Покрытие услуг</h3><p>Навыки доступных мастеров соответствуют требованиям услуги.</p></div><div class="admin-coverage-grid"><div v-for="c in coverage" :key="c.name" :title="c.name+': '+c.covered+' из '+c.total+' услуг'"><span><DeviceArt :name="equipmentArt(c.name)"/></span><div><strong>{{c.name}}</strong><small>{{c.covered}} / {{c.total}} услуг</small><i><b :style="{width:c.covered/c.total*100+'%'}"/></i></div></div></div></div></section>
 <section v-else-if="entity==='points'" class="admin-story admin-point-story"><div class="admin-story-copy"><span class="admin-visual-eyebrow">ОЧНОЕ ОБСЛУЖИВАНИЕ</span><h2>Точки приёма и текущая загрузка</h2><p>Активные точки доступны клиентам при выборе ремонта в сервисе. Адреса здесь и в форме заявки должны совпадать.</p><div class="admin-client-facts"><div><strong>{{activePoints}}</strong><span>активных точек приёма</span></div><div><strong>{{dropoff}}</strong><span>активных ремонтов в сервисе</span></div></div><span class="admin-context-note"><SvgIcon name="store" :size="16"/>Отключённые точки остаются в истории заявок</span></div></section>
 <section v-else-if="entity==='audit'" class="admin-story admin-audit-story"><div class="admin-story-photo"><img :src="auditPhoto" alt="Специалист проверяет записи о выполненном ремонте" loading="lazy"/></div><div class="admin-story-copy"><span class="admin-visual-eyebrow">ПРОЗРАЧНАЯ РАБОТА СЕРВИСА</span><h2>За каждым изменением —<br/>понятная история.</h2><p>События текущего журнала по ролям. Выберите исполнителя, чтобы проверить его действия.</p><div class="admin-audit-distribution"><i v-for="r in roles.filter(r=>r.count)" :key="r.key" :style="{width:r.count/Math.max(1,auditEvents.length)*100+'%',background:r.color}"/></div><div class="admin-audit-role-buttons"><button v-for="r in roles" :key="r.key" :aria-pressed="selected===r.key" :style="{'--role-color':r.color}" type="button" @click="emit('filter',selected===r.key?'':r.key)"><span/><div>{{r.label}}<strong>{{r.count}}</strong></div></button></div><span class="admin-context-note"><SvgIcon name="shield" :size="16"/>Просмотр страниц не создаёт события аудита</span></div></section>
 <section v-else-if="entity==='suppliers'" class="admin-partner-context"><div class="admin-context-heading"><div><span class="admin-visual-eyebrow">ЦЕПОЧКА СНАБЖЕНИЯ</span><h2>Партнёры, на которых держится ремонт</h2></div><span>{{countLabel(partners.length,'активный поставщик','активных поставщика','активных поставщиков')}}</span></div><div class="admin-partner-grid"><button v-for="s in partners" :key="s.id" type="button" @click="emit('filter',s.name)"><div class="admin-partner-top"><span>{{s.name.split(/[^а-яa-zё]+/i).filter(Boolean).map(n=>n[0]).join('').slice(0,2).toUpperCase()}}</span><div><h3>{{s.name}}</h3><small>{{s.contact_person}}</small></div><SvgIcon name="arrowRight" :size="16"/></div><div class="admin-partner-parts"><span v-for="p in s.parts.slice(0,3)" :key="p.id"><PartArt :kind="adminPartKind(p.id).kind"/></span><small v-if="!s.parts.length">Каталог деталей пока не заполнен</small><small v-else>{{countLabel(s.parts.length,'позиция','позиции','позиций')}} в каталоге</small></div><footer><span>Открытые заказы</span><strong>{{s.orders.length}}</strong></footer></button></div></section>
</template>
